package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_performance_intervention",uniqueConstraints=@UniqueConstraint(name="uk_spms_intervention_final",columnNames={"agency_id","final_rating_id"}))
public class PerformanceIntervention extends RspAuditedEntity{public enum Status{OPEN,ISSUED,ACKNOWLEDGED,IN_PROGRESS,COMPLETED,CLOSED}@Column(name="final_rating_id",nullable=false,length=36)private String finalRatingId;@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="rule_id",nullable=false,length=36)private String ruleId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Enumerated(EnumType.STRING)@Column(name="intervention_action",nullable=false,length=30)private PerformanceInterventionRule.Action action;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(length=4000)private String objectives;@Column(name="support_plan",length=4000)private String supportPlan;@Column(name="accountable_employee_no",length=100)private String accountableEmployeeNo;@Column(name="starts_on")private LocalDate startsOn;@Column(name="ends_on")private LocalDate endsOn;@Column(name="employee_response",length=2000)private String employeeResponse;@Column(name="issued_by",length=100)private String issuedBy;@Column(name="issued_at")private Instant issuedAt;@Column(name="acknowledged_at")private Instant acknowledgedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="closed_at")private Instant closedAt;@Column(name="closure_reason",length=2000)private String closureReason;protected PerformanceIntervention(){}public PerformanceIntervention(String a,String finalId,String ratingCase,String rule,String employee,PerformanceInterventionRule.Action action){super(a);finalRatingId=requiredText(finalId,"finalRatingId");ratingCaseId=requiredText(ratingCase,"ratingCaseId");ruleId=requiredText(rule,"ruleId");employeeNo=requiredText(employee,"employeeNo");this.action=action;status=Status.OPEN;}public void issue(String objectives,String support,String accountable,LocalDate starts,LocalDate ends,String actor,Instant at){if(status!=Status.OPEN)throw new IllegalStateException("Only an open intervention may be issued");this.objectives=requiredText(objectives,"objectives");supportPlan=requiredText(support,"supportPlan");accountableEmployeeNo=requiredText(accountable,"accountableEmployeeNo");startsOn=starts;if(starts==null||ends==null||ends.isBefore(starts))throw new IllegalArgumentException("A valid intervention date range is required");endsOn=ends;issuedBy=requiredText(actor,"actor");issuedAt=at;status=Status.ISSUED;}public void acknowledge(String employee,String response,Instant at){if(status!=Status.ISSUED)throw new IllegalStateException("Only an issued intervention may be acknowledged");if(!employeeNo.equalsIgnoreCase(employee))throw new IllegalArgumentException("Only the subject employee may acknowledge the intervention");employeeResponse=optionalText(response);acknowledgedAt=at;status=Status.ACKNOWLEDGED;}public void start(){if(status!=Status.ACKNOWLEDGED&&status!=Status.ISSUED)throw new IllegalStateException("Intervention is not ready to start");status=Status.IN_PROGRESS;}public void complete(Instant at){if(status!=Status.IN_PROGRESS)throw new IllegalStateException("Only an in-progress intervention may be completed");completedAt=at;status=Status.COMPLETED;}public void close(String reason,Instant at){if(status!=Status.COMPLETED)throw new IllegalStateException("Only a completed intervention may be closed");closureReason=requiredText(reason,"reason");closedAt=at;status=Status.CLOSED;}public String getFinalRatingId(){return finalRatingId;}public String getRatingCaseId(){return ratingCaseId;}public String getRuleId(){return ruleId;}public String getEmployeeNo(){return employeeNo;}public PerformanceInterventionRule.Action getAction(){return action;}public Status getStatus(){return status;}public String getObjectives(){return objectives;}public String getSupportPlan(){return supportPlan;}public String getAccountableEmployeeNo(){return accountableEmployeeNo;}public LocalDate getStartsOn(){return startsOn;}public LocalDate getEndsOn(){return endsOn;}public String getEmployeeResponse(){return employeeResponse;}public String getIssuedBy(){return issuedBy;}public Instant getIssuedAt(){return issuedAt;}public Instant getAcknowledgedAt(){return acknowledgedAt;}public Instant getCompletedAt(){return completedAt;}public Instant getClosedAt(){return closedAt;}public String getClosureReason(){return closureReason;}}
